BEGIN;
-- Keep the generated bytes stable across retries; do not regenerate an emailed report.
ALTER TABLE public.tw_finance_mail_jobs ADD COLUMN attachments jsonb NOT NULL DEFAULT '[]'::jsonb
 CHECK(jsonb_typeof(attachments)='array' AND jsonb_array_length(attachments)<=1 AND octet_length(attachments::text)<=2800000);
COMMIT;
